package com.skyclone.mod.skills;

import com.google.gson.Gson;
import com.skyclone.api.skill.SkillType;
import com.skyclone.api.stat.Stat;

import java.io.Reader;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The whole skill table, loaded from {@code data/skills/skills.json} (generated by
 * {@code tools/gen/skills/gen_skills.py} from the reference API dump). PURE: no Bukkit, so the
 * unit tests run the shipping numbers.
 *
 * <p>XP is cumulative: level L is reached at {@code total(L)} XP. Level 0 is 0 XP.
 */
public final class SkillTable {

    /** One skill as it sits in the JSON. Public fields for Gson. */
    public static final class Spec {
        public String id;
        public String name;
        public List<String> description = new ArrayList<>();
        public int maxLevel;
        public int defaultCap;
        public List<String> capHint = new ArrayList<>();
        public String perkName;
        public String perkStat;
        public String perkText;
        public String perk2Text;
        public List<Level> levels = new ArrayList<>();
    }

    public static final class Level {
        public int level;
        public double total;
        public double coins;
        public int sbxp;
        public Map<String, Double> stats = new LinkedHashMap<>();
        /** Cumulative perk value at this level (Farming Fortune 4, 8, 12... / Warrior 4%...). */
        public double perk;
        /** Second perk value (Taming exp share %), 0 when none. */
        public double perk2;
        public List<Unlock> unlocks = new ArrayList<>();
    }

    /** A non-numeric reward line. {@code type}: access, reforge_stone, power_stone, enchant, sea_creature, recipe, furniture, text. */
    public static final class Unlock {
        public String type;
        public String id;
        public String name;
    }

    static final class Root {
        int version;
        String source;
        Map<String, Spec> skills = new LinkedHashMap<>();
    }

    private final EnumMap<SkillType, Spec> specs = new EnumMap<>(SkillType.class);
    /** [skill][level 0..max] cumulative XP. */
    private final EnumMap<SkillType, double[]> totals = new EnumMap<>(SkillType.class);
    private final java.util.HashMap<SkillType, Stat> perkStats = new java.util.HashMap<>();
    /** [skill][level 0..max] -> cumulative stat rewards (perk stat NOT included). */
    private final EnumMap<SkillType, List<EnumMap<Stat, Double>>> cumulativeStats = new EnumMap<>(SkillType.class);

    public static SkillTable load(Reader json) {
        Root root = new Gson().fromJson(json, Root.class);
        if (root == null || root.skills == null) throw new IllegalStateException("skills.json is empty");
        SkillTable t = new SkillTable();
        for (SkillType type : SkillType.values()) {
            Spec s = root.skills.get(type.name());
            if (s == null) throw new IllegalStateException("skills.json has no " + type.name());
            if (s.levels.size() != s.maxLevel)
                throw new IllegalStateException(type + ": " + s.levels.size() + " levels for max " + s.maxLevel);
            t.specs.put(type, s);
            double[] tot = new double[s.maxLevel + 1];
            List<EnumMap<Stat, Double>> cum = new ArrayList<>(s.maxLevel + 1);
            EnumMap<Stat, Double> run = new EnumMap<>(Stat.class);
            cum.add(new EnumMap<>(Stat.class));
            if (s.perkStat != null && Stat.parse(s.perkStat) == null)
                throw new IllegalStateException(type + ": unknown perk stat " + s.perkStat);
            t.perkStats.put(type, s.perkStat == null ? null : Stat.parse(s.perkStat));
            for (int i = 0; i < s.maxLevel; i++) {
                Level lv = s.levels.get(i);
                if (lv.level != i + 1) throw new IllegalStateException(type + ": level " + lv.level + " at index " + i);
                tot[i + 1] = lv.total;
                for (Map.Entry<String, Double> e : lv.stats.entrySet()) {
                    Stat st = Stat.parse(e.getKey());
                    if (st == null) throw new IllegalStateException(type + ": unknown stat " + e.getKey());
                    run.merge(st, e.getValue(), Double::sum);
                }
                cum.add(new EnumMap<>(run));
            }
            t.totals.put(type, tot);
            t.cumulativeStats.put(type, cum);
        }
        return t;
    }

    // ---- lookups ------------------------------------------------------------------------------

    public Spec spec(SkillType s) { return specs.get(s); }

    /** Highest level the data defines (Foraging 57, the same as {@link SkillType#maxLevel} since wave 5). */
    public int maxLevel(SkillType s) { return specs.get(s).maxLevel; }

    /** Default cap before any unlock (Farming/Taming/Foraging 50, everything else = max). */
    public int defaultCap(SkillType s) { return Math.min(specs.get(s).defaultCap, maxLevel(s)); }

    /** The level row (1-based). Null outside 1..max. */
    public Level level(SkillType s, int level) {
        Spec sp = specs.get(s);
        if (level < 1 || level > sp.maxLevel) return null;
        return sp.levels.get(level - 1);
    }

    /** Cumulative XP to reach {@code level} (0 for level 0, clamped to max). */
    public double total(SkillType s, int level) {
        double[] t = totals.get(s);
        if (level <= 0) return 0;
        return t[Math.min(level, t.length - 1)];
    }

    /** XP needed to go from level-1 to level. */
    public double step(SkillType s, int level) { return total(s, level) - total(s, level - 1); }

    /** Uncapped level for a cumulative XP amount (binary search). */
    public int levelFor(SkillType s, double xp) {
        double[] t = totals.get(s);
        if (!(xp >= t[1])) return 0;               // also catches NaN
        int lo = 1, hi = t.length - 1;
        while (lo < hi) {
            int mid = (lo + hi + 1) >>> 1;
            if (t[mid] <= xp) lo = mid; else hi = mid - 1;
        }
        return lo;
    }

    /** Level for XP, never above {@code cap}. */
    public int levelFor(SkillType s, double xp, int cap) {
        return Math.max(0, Math.min(levelFor(s, xp), Math.min(cap, maxLevel(s))));
    }

    /** XP into the current level (for a progress bar). At max level: XP beyond the max (overflow). */
    public double progress(SkillType s, double xp, int level) {
        return Math.max(0, xp - total(s, level));
    }

    /** XP needed for the next level, 0 at max level. */
    public double needed(SkillType s, int level) {
        if (level >= maxLevel(s)) return 0;
        return step(s, level + 1);
    }

    /** The stat the perk grants (Farming Fortune...), or null for perks that are not a stat. */
    public Stat perkStat(SkillType s) { return perkStats.get(s); }

    /** Cumulative per-level stat rewards at {@code level}, WITHOUT the perk stat. Do not mutate. */
    public Map<Stat, Double> statsAt(SkillType s, int level) {
        List<EnumMap<Stat, Double>> cum = cumulativeStats.get(s);
        return cum.get(Math.max(0, Math.min(level, cum.size() - 1)));
    }

    /** Cumulative perk value at {@code level} (0 at level 0). */
    public double perk(SkillType s, int level) {
        Level l = level(s, Math.min(level, maxLevel(s)));
        return l == null ? 0 : l.perk;
    }

    public double perk2(SkillType s, int level) {
        Level l = level(s, Math.min(level, maxLevel(s)));
        return l == null ? 0 : l.perk2;
    }

    /** Sum of coin rewards for levels 1..level. */
    public double coinsThrough(SkillType s, int level) {
        double sum = 0;
        for (int i = 1; i <= Math.min(level, maxLevel(s)); i++) sum += level(s, i).coins;
        return sum;
    }

    /** Sum of SkyBlock XP rewards for levels 1..level. */
    public int sbxpThrough(SkillType s, int level) {
        int sum = 0;
        for (int i = 1; i <= Math.min(level, maxLevel(s)); i++) sum += level(s, i).sbxp;
        return sum;
    }

    /** Skill average of the given levels, over the non-cosmetic skills (API contract). */
    public static double average(Map<SkillType, Integer> levels) {
        return average(levels, s -> !s.cosmetic);
    }

    /** Skill average over the skills {@code counted} accepts (wave 5: the Hunting dial decides for Hunting). */
    public static double average(Map<SkillType, Integer> levels, java.util.function.Predicate<SkillType> counted) {
        int n = 0;
        double sum = 0;
        for (SkillType s : SkillType.values()) {
            if (!counted.test(s)) continue;
            n++;
            sum += levels.getOrDefault(s, 0);
        }
        return n == 0 ? 0 : sum / n;
    }

    /**
     * Validates the table against itself: strictly increasing XP, every level row present, every
     * stat parses. Returns null when fine, else the first problem. Used by a self-test and the unit test.
     */
    public String validate() {
        for (SkillType s : SkillType.values()) {
            double[] t = totals.get(s);
            for (int i = 1; i < t.length; i++) {
                if (!(t[i] > t[i - 1])) return s + ": XP not increasing at level " + i;
                if (levelFor(s, t[i]) != i) return s + ": levelFor(total(" + i + ")) != " + i;
                if (levelFor(s, t[i] - 0.01) != i - 1) return s + ": levelFor just under level " + i;
            }
            Spec sp = specs.get(s);
            if (sp.perkText != null && perk(s, sp.maxLevel) <= 0) return s + ": perk text but no perk values";
            if (defaultCap(s) < 1) return s + ": default cap < 1";
        }
        return null;
    }
}
